from click.core import Command, Context, Option


class _EmptyLike:
    """A non-string default value that compares equal to the empty string."""

    def __eq__(self, other):
        return isinstance(other, str) and other == ""

    def __hash__(self):
        return hash("empty-like")

    def __str__(self):
        return "<empty-like>"


def test_get_help_extra_stringifies_non_string_default_equal_to_empty_string():
    # A default value that is not a str but compares equal to "" must still
    # be rendered via str() in the help extra, not collapsed to the literal
    # '""' placeholder that is reserved for actual empty string defaults.
    opt = Option(["--opt"], show_default=True, default=_EmptyLike())
    ctx = Context(Command("cmd"))

    extra = opt.get_help_extra(ctx)

    assert extra["default"] == "<empty-like>"

